const n = Number.parseInt(process.argv[2], 10);

function Node(left, right) {
    this.left = left;
    this.right = right;
}

function buildTree(depth) {
    if (depth === 0) {
        return new Node(null, null);
    }
    return new Node(buildTree(depth - 1), buildTree(depth - 1));
}

function countNodes(tree) {
    if (tree.left === null) {
        return 1;
    }
    return 1 + countNodes(tree.left) + countNodes(tree.right);
}

function main() {
    const output = [];

    let stretchTree = buildTree(n + 1);
    const stretchCheck = countNodes(stretchTree);
    stretchTree = null;

    output.push(`stretch tree of depth ${n + 1}\t check: ${stretchCheck}`);

    let longLivedTree = buildTree(n);

    for (let depth = 4; depth <= n; depth += 2) {
        const iterations = 2 ** (n - depth + 4);
        let checksum = 0;

        for (let i = 0; i < iterations; i++) {
            checksum += countNodes(buildTree(depth));
        }

        output.push(`${iterations}\t trees of depth ${depth}\t check: ${checksum}`);
    }

    output.push(`long lived tree of depth ${n}\t check: ${countNodes(longLivedTree)}`);
    longLivedTree = null;

    process.stdout.write(output.join('\n') + '\n');
}

